#!/usr/bin/env Rscript
source("code/01_common.R");base<-file.path(r2,"TNK");runs<-c("A_baseline_origident_theta2_lambda1","B_origident_theta4_lambda1","C_origident_theta6_lambda0.5","D_dataset_theta4_lambda1");cmpdir<-file.path(base,"comparison");dir.create(cmpdir,recursive=TRUE,showWarnings=FALSE)
metrics<-do.call(rbind,lapply(runs,function(x)read.csv(file.path(base,x,paste0("sensitivity_metrics_",x,".csv")),check.names=FALSE)))
tracksets<-list(CD8_GZMK_core=c(1,3,4,16),CD8_GZMK_island_review=c(2,18),Exhausted_CD8_review=c(0,9),CD4_Helper_review=c(7,8,10,13,14),Treg_review=c(5,6,15),NK_review=c(11,12))
tracking<-list();pdataset<-list();pround1<-list()
for(run in runs){o<-qs::qread(file.path(base,run,paste0("TNK_round2_",run,".qs")));r1c<-as.character(o$cluster_v2_round1);r2c<-as.character(o$cluster_v2_round2);tracking[[run]]<-do.call(rbind,lapply(names(tracksets),function(nm){sel<-r1c%in%as.character(tracksets[[nm]]);z<-sort(table(r2c[sel]),decreasing=TRUE);p<-z/sum(z);data.frame(run=run,tracked_family=nm,n_cells=sum(sel),dominant_round2_cluster=names(z)[1],dominant_fraction=as.numeric(p[1]),n_round2_clusters_to_cover_80pct=which(cumsum(p)>=.8)[1],round2_clusters_by_fraction=paste0(names(head(p,5)),"(",round(as.numeric(head(p,5)),3),")",collapse=";"),stringsAsFactors=FALSE)}));pdataset[[run]]<-umap_plot(o,"dataset");pround1[[run]]<-umap_plot(o,"cluster_v2_round1",label=TRUE);rm(o);invisible(gc())}
tracking<-do.call(rbind,tracking);write.csv(tracking,file.path(cmpdir,"TNK_round1_family_tracking_across_runs.csv"),row.names=FALSE)
baseline<-metrics[metrics$run==runs[1],];metrics$overcorrection_warning<-metrics$round1_family_neighbor_preservation<baseline$round1_family_neighbor_preservation-.05|metrics$round1_cluster_to_round2_NMI<baseline$round1_cluster_to_round2_NMI-.05;metrics$dataset_specific_island_warning<-metrics$n_dataset_gt90>0
norm01<-function(x)if(diff(range(x))==0)rep(.5,length(x))else(x-min(x))/diff(range(x));metrics$balanced_auxiliary_score<-.35*norm01(metrics$dataset_neighbor_mixing)+.15*norm01(metrics$specimen_neighbor_mixing)+.3*norm01(metrics$round1_family_neighbor_preservation)+.2*norm01(metrics$round1_cluster_to_round2_NMI);eligible<-which(!metrics$overcorrection_warning);best<-eligible[which.max(metrics$balanced_auxiliary_score[eligible])];metrics$recommended<-FALSE;metrics$recommended[best]<-TRUE;metrics$notes<-ifelse(metrics$overcorrection_warning,"Quantitative biological-preservation drop vs baseline; manual overcorrection review required",ifelse(metrics$dataset_specific_island_warning,"Biology preserved by auxiliary metrics but one or more >90% dataset clusters remain","Balanced auxiliary mixing/preservation profile"));write.csv(metrics,file.path(cmpdir,"TNK_HARMONY_SENSITIVITY_COMPARISON.csv"),row.names=FALSE)
pds<-wrap_plots(pdataset,nrow=1,guides="collect")&theme(legend.position="bottom");save_pair(pds,file.path(cmpdir,"TNK_ABCD_dataset_mixing_comparison"),22,6)
pr1<-wrap_plots(pround1,nrow=1,guides="collect")&theme(legend.position="bottom");save_pair(pr1,file.path(cmpdir,"TNK_ABCD_round1_cluster_structure_comparison"),22,6)
rec<-metrics$run[metrics$recommended];fmt<-function(x)format(round(x,4),nsmall=4);lines<-c("# TNK Harmony sensitivity summary","","All four runs used the identical 124,746-cell set, 3,000-HVG logic, shared 50-PC PCA, dimensions 1:30, UMAP settings, resolution 0.8, seed, and frozen marker panel. No combined `dataset + orig.ident` correction was used.","","## Quantitative auxiliary comparison","",paste0("- ",metrics$run,": clusters=",metrics$n_clusters,"; dataset neighbor mixing=",fmt(metrics$dataset_neighbor_mixing),"; specimen neighbor mixing=",fmt(metrics$specimen_neighbor_mixing),"; Round1-family preservation=",fmt(metrics$round1_family_neighbor_preservation),"; Round1→Round2 NMI=",fmt(metrics$round1_cluster_to_round2_NMI),"; >90% dataset clusters=",metrics$n_dataset_gt90,"; overcorrection warning=",metrics$overcorrection_warning),"","## Biological preservation audit","",paste0("- ",tracking$run," / ",tracking$tracked_family,": dominant Round2 cluster ",tracking$dominant_round2_cluster," (",round(tracking$dominant_fraction,3),"); clusters covering 80% = ",tracking$n_round2_clusters_to_cover_80pct),"","## Recommendation","",paste0("Recommended for manual selection: `",rec,"`. This recommendation maximizes a balanced auxiliary score combining dataset/specimen neighbor mixing with Round1-family neighborhood preservation and Round1→Round2 NMI, while excluding runs flagged for overcorrection. It is not based on UMAP appearance alone and is not a final subtype annotation."),"","Manual review must still prioritize CD8 GZMK 1/3/4/16 and islands 2/18, Exhausted 0/9, Helper 7/8/10/13/14, Treg 5/6/15, and NK 11/12 using the paired comparison figures, mapping tables, DotPlots, and markers.","","TNK_ROUND2_SENSITIVITY_STATUS = READY_FOR_MANUAL_SELECTION");writeLines(lines,file.path(cmpdir,"TNK_HARMONY_SENSITIVITY_SUMMARY.md"));message("TNK_COMPARISON_DONE recommended=",rec)
